import {MEDICAL_CART_META_V12} from './medical-cart-meta-v14.js';
import {HESTER_META} from './hester-meta-v14.js';
import {DEEP_BOSS_META,DEEP_PORTRAIT_META,DEEP_PROP_META} from './deep-art-meta-v14.js';
import {MEDICAL_META} from './medical-meta-v14.js';
import {COURT_ACTOR_META} from './court-actor-meta-v14.js';
export function installV11Frames(bank,name){const meta={medicalCart:MEDICAL_CART_META_V12,hesterActions:HESTER_META,deepBosses:DEEP_BOSS_META,deepPortraits:DEEP_PORTRAIT_META,deepProps:DEEP_PROP_META,medicalProps:MEDICAL_META,courtActors:COURT_ACTOR_META}[name];if(!meta)return;bank.frames[name]=meta.items.map(m=>{const[x,y,w,h]=m.sourceRect,f={x,y,w,h,cell:{x,y,w,h},meta:m};if(m.clipPolygon){const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.beginPath();m.clipPolygon.forEach(([px,py],i)=>i?ctx.lineTo(px,py):ctx.moveTo(px,py));ctx.closePath();ctx.clip();ctx.drawImage(bank.images[name],x,y,w,h,0,0,w,h);f.cached=c;}return f;});}
export function drawV11Frame(c,bank,name,index,x,y,unit,flip=false){const f=bank.frame(name,index);if(!f)return;const[ax,ay]=f.meta.anchorInSourceRect;c.save();c.translate(Math.round(x),Math.round(y));if(flip)c.scale(-1,1);c.imageSmoothingEnabled=true;if(f.cached)c.drawImage(f.cached,-ax*unit,-ay*unit,f.w*unit,f.h*unit);else c.drawImage(bank.images[name],f.x,f.y,f.w,f.h,-ax*unit,-ay*unit,f.w*unit,f.h*unit);c.restore();}
export function drawV11Monster(c,bank,a,time){if(a.type==='bloodDemon'){const im=bank.images.bloodDemon;if(!im)return true;const i=a.wind>0||a.attackAnim>0?3:a.moving?[1,0,2,0][Math.floor((a.walkDistance||0)/36)%4]:0,anchors=[[324.5,605],[336,598],[328.5,596],[330,604]],k=180/590;c.save();c.translate(Math.round(a.x),Math.round(a.y));if(Math.cos(a.angle||0)<0)c.scale(-1,1);if(a.fall){c.globalAlpha=.42;c.rotate(-.3);}c.imageSmoothingEnabled=true;c.drawImage(im,i%2*627,Math.floor(i/2)*627,627,627,-anchors[i][0]*k,-anchors[i][1]*k,627*k,627*k);c.restore();return true;}const row={ironScuttler:0,furnaceSentinel:1,odric:2,martha:3,severin:4}[a.type];if(row===undefined)return false;const phase=a.wind>0||a.attackAnim>0?3:a.moving?[1,0,2,0][Math.floor((a.walkDistance||0)/29)%4]:0;const unit=[110,132,122,114,134][row]/DEEP_BOSS_META.items[row*4].referenceHeight;c.save();if(a.fall){c.globalAlpha=.65;c.translate(a.x,a.y);c.rotate(Math.min(1,a.fall)*({odric:-1.35,martha:2.2,severin:1.35}[a.type]||1.35));drawV11Frame(c,bank,'deepBosses',row*4+phase,0,0,unit,Math.cos(a.angle||0)<0);}else drawV11Frame(c,bank,'deepBosses',row*4+phase,a.x,a.y,unit,Math.cos(a.angle||0)<0);c.restore();return true;}
export function drawCourtActor(c,bank,a,time,size){if(a.id==='hester'){const t=a.gesture?Math.max(0,time-(a.gestureAt||0)):9;const index=t<.08?0:t<.24?1:t<.34?2:t<.56?3:0;const m=HESTER_META.items[index];drawV11Frame(c,bank,'hesterActions',index,a.x,a.y,size/HESTER_META.renderScaleReferenceHeight*(m.bodyScale||1),false);return true;}if(!['dancer1','dancer2','servant'].includes(a.id))return false;let index=4;if(a.id==='servant')index=a.pose==='collect_shards'?7:a.fall>.5?6:a.pose==='offbalance'?5:4;else index=a.fall>.2?3:a.idleAnimation==='dance'&&!a.speaking?[0,1,2,3,2,1][Math.floor(time/.6+(a.id==='dancer2'?2:0))%6]:3;drawV11Frame(c,bank,'courtActors',index,a.x,a.y,size/COURT_ACTOR_META.renderScaleReferenceHeight,Math.cos(a.angle||0)<0);return true;}
export function drawMedicalBed(c,bank,x,y,cart=false){if(cart)drawV11Frame(c,bank,'medicalCart',0,x,y,84/MEDICAL_CART_META_V12.items[0].bedUsableLength);else drawV11Frame(c,bank,'medicalProps',1,x,y,.27);}
export function patientPosition(x,y,cart=false){const m=cart?MEDICAL_CART_META_V12.items[0]:MEDICAL_META.items[1],unit=cart?84/m.bedUsableLength:.27,a=m.footAnchor,b=m.bedFootAnchor;return {x:x+(b[0]-a[0])*unit,y:y+(b[1]-a[1])*unit,angle:(90+m.bedAxisDegrees)*Math.PI/180,size:m.bedUsableLength*unit};}
